action.command:
cat > /tmp/validate-app.mjs << 'EOF'
import { chromium } from '/workspace/node_modules/playwright/index.mjs';

const browser = await chromium.launch({ headless: true });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
const consoleErrors = [];
const pageErrors = [];
page.on('console', (m) => { if (m.type() === 'error') consoleErrors.push(m.text()); });
page.on('pageerror', (e) => pageErrors.push(String(e)));

await page.goto('http://localhost:5173/', { waitUntil: 'networkidle', timeout: 60000 });
await page.waitForTimeout(2000);

const title = await page.title();
const rootHTMLLen = await page.evaluate(() => document.getElementById('root')?.innerHTML.length ?? 0);
const bodyText = await page.evaluate(() => document.body.innerText.slice(0, 1500));
const counts = await page.evaluate(() => ({
  buttons: document.querySelectorAll('button').length,
  inputs: document.querySelectorAll('input').length,
  sections: document.querySelectorAll('section').length,
  canvasOrList: document.querySelectorAll('[class*="module"], [class*="Module"]').length,
}));
await page.screenshot({ path: '/tmp/formulardesigner-screenshot.png', fullPage: false });

console.log('TITLE:', title);
console.log('ROOT_HTML_LENGTH:', rootHTMLLen);
console.log('COUNTS:', JSON.stringify(counts));
console.log('PAGE_ERRORS:', JSON.stringify(pageErrors));
console.log('CONSOLE_ERRORS:', JSON.stringify(consoleErrors.slice(0, 10)));
console.log('BODY_TEXT_START>>>');
console.log(bodyText);
console.log('<<<BODY_TEXT_END');
await browser.close();
EOF
node /tmp/validate-app.mjs; echo "EXIT: $?"

